namespace PixelForge {
public static class BrushFootprint {
    // Diameter is in source pixels, with a consistent raster center for even sizes.
    public static void Visit(int x,int y,int size,Action<int,int> paint){size=Math.Max(1,Math.Min(128,size));int low=-(size-1)/2;double center=low+(size-1)/2.0,radius=size/2.0;for(int dy=low;dy<low+size;dy++)for(int dx=low;dx<low+size;dx++)if((dx-center)*(dx-center)+(dy-center)*(dy-center)<=radius*radius)paint(x+dx,y+dy);}
}
public static class LayerMasks {
    static readonly ConditionalWeakTable<Frame,ConditionalWeakTable<Frame,Frame>> cache=new ConditionalWeakTable<Frame,ConditionalWeakTable<Frame,Frame>>();
    public static Frame Full(int w,int h,bool visible){var f=new Frame(w,h);for(int p=0;p<f.Data.Length;p+=4){f.Data[p]=f.Data[p+1]=f.Data[p+2]=255;f.Data[p+3]=(byte)(visible?255:0);}return f;}
    public static Frame Apply(Frame frame,Frame mask){if(mask==null)return frame;if(frame.W!=mask.W||frame.H!=mask.H)throw new Exception("Размер маски не совпадает со слоем.");return cache.GetOrCreateValue(frame).GetValue(mask,m=>{var result=frame.Clone();for(int p=3;p<result.Data.Length;p+=4)result.Data[p]=(byte)((result.Data[p]*m.Data[p]+127)/255);return result;});}
    public static void Shape(Frame mask,int x0,int y0,int x1,int y1,bool ellipse,bool visible){int left=Math.Min(x0,x1),right=Math.Max(x0,x1),top=Math.Min(y0,y1),bottom=Math.Max(y0,y1);double cx=(left+right+1)/2.0,cy=(top+bottom+1)/2.0,rx=(right-left+1)/2.0,ry=(bottom-top+1)/2.0;for(int y=Math.Max(0,top);y<=Math.Min(mask.H-1,bottom);y++)for(int x=Math.Max(0,left);x<=Math.Min(mask.W-1,right);x++){double dx=(x+.5-cx)/rx,dy=(y+.5-cy)/ry;if(!ellipse||dx*dx+dy*dy<=1)mask.Data[(y*mask.W+x)*4+3]=(byte)(visible?255:0);}}
}
public sealed partial class MainWindow {
    Slider spriteBrushSlider,spriteEraseSlider;
    void AddBrushSizes(Panel side){spriteBrushSlider=AddSizeSlider(side,"Размер кисти, px",editor.BrushSize,n=>editor.BrushSize=n);spriteEraseSlider=AddSizeSlider(side,"Размер ластика, px",editor.EraseSize,n=>editor.EraseSize=n);}
    void SyncBrushSizes(){if(spriteBrushSlider!=null)spriteBrushSlider.Value=editor.BrushSize;if(spriteEraseSlider!=null)spriteEraseSlider.Value=editor.EraseSize;}
    internal static Slider AddSizeSlider(Panel panel,string name,int initial,Action<int> changed){var label=new TextBlock {Text=name+": "+initial,TextWrapping=TextWrapping.Wrap};panel.Children.Add(label);var slider=new Slider {Minimum=1,Maximum=64,Value=initial,TickFrequency=1,IsSnapToTickEnabled=true,Margin=new Thickness(0,3,0,10)};slider.ValueChanged+=(s,e)=>{int value=(int)Math.Round(slider.Value);label.Text=name+": "+value;changed(value);};panel.Children.Add(slider);return slider;}
}
public sealed class MaskScenePreview {
    public Cutscene Scene;public SceneLayer Layer;public double Time;public Frame BaseMask;
}
public sealed class MaskCanvas : FrameworkElement {
    public Frame Source,Mask;public int Size=5;public string Tool="Кисть";public bool Hide,Ghost=true,SceneMode;public MaskScenePreview Preview;
    public Action Begin,Changed,End;Point start,last,hover=new Point(-1,-1);bool active;Frame before;
    public MaskCanvas(){Focusable=true;ClipToBounds=true;MouseLeftButtonDown+=(s,e)=>{if(Source==null)return;var p=Pixel(e.GetPosition(this));if(p.X<0)return;Focus();if(Begin!=null)Begin();before=Mask.Clone();start=last=p;active=true;CaptureMouse();Apply(p);};MouseMove+=(s,e)=>{var p=Pixel(e.GetPosition(this));hover=p;if(active&&p.X>=0){if(Tool=="Кисть"||Tool=="Ластик"){int steps=(int)Math.Max(Math.Abs(p.X-last.X),Math.Abs(p.Y-last.Y));for(int n=0;n<=steps;n++)Apply(new Point(Math.Round(last.X+(p.X-last.X)*n/Math.Max(1,steps)),Math.Round(last.Y+(p.Y-last.Y)*n/Math.Max(1,steps))));}else{Mask=before.Clone();Apply(p);}last=p;}InvalidateVisual();};MouseLeftButtonUp+=(s,e)=>Finish();LostMouseCapture+=(s,e)=>Finish();MouseLeave+=(s,e)=>{hover=new Point(-1,-1);InvalidateVisual();};}
    void Finish(){if(!active)return;active=false;if(IsMouseCaptured)ReleaseMouseCapture();before=null;if(End!=null)End();}
    void Apply(Point p){bool visible=!(Hide||Tool=="Ластик");if(Tool=="Кисть"||Tool=="Ластик")BrushFootprint.Visit((int)p.X,(int)p.Y,Size,(x,y)=>{if(x>=0&&y>=0&&x<Mask.W&&y<Mask.H)Mask.Data[(y*Mask.W+x)*4+3]=(byte)(visible?255:0);});else{if(Tool=="Круг"){double diameter=Math.Max(Math.Abs(p.X-start.X),Math.Abs(p.Y-start.Y));p=new Point(start.X+(p.X<start.X?-diameter:diameter),start.Y+(p.Y<start.Y?-diameter:diameter));}LayerMasks.Shape(Mask,(int)start.X,(int)start.Y,(int)p.X,(int)p.Y,Tool=="Эллипс"||Tool=="Круг",visible);}if(Changed!=null)Changed();InvalidateVisual();}
    bool OnScene {get{return SceneMode&&Preview!=null;}}
    Rect Area(){if(Source==null)return Rect.Empty;int w=OnScene?Preview.Scene.Width:Source.W,h=OnScene?Preview.Scene.Height:Source.H;double z=Math.Max(.001,Math.Min((ActualWidth-24)/w,(ActualHeight-24)/h));if(z>=1)z=Math.Max(1,Math.Floor(z));return new Rect((ActualWidth-w*z)/2,(ActualHeight-h*z)/2,w*z,h*z);}
    public static Matrix LayerTransform(SceneLayer layer,Frame source,double time){double scale=layer.Value(layer.Scale,layer.EndScale,time);var matrix=Matrix.Identity;matrix.Scale(scale,scale);matrix.RotateAt(layer.Value(layer.Rotation,layer.EndRotation,time),source.W*scale/2,source.H*scale/2);matrix.Translate(layer.Value(layer.X,layer.EndX,time),layer.Value(layer.Y,layer.EndY,time));return matrix;}
    Point Pixel(Point p){if(Source==null)return new Point(-1,-1);var area=Area();if(!area.Contains(p))return new Point(-1,-1);Point local;if(OnScene){local=new Point((p.X-area.X)*Preview.Scene.Width/area.Width,(p.Y-area.Y)*Preview.Scene.Height/area.Height);var inverse=LayerTransform(Preview.Layer,Source,Preview.Time);inverse.Invert();local=inverse.Transform(local);}else local=new Point((p.X-area.X)*Source.W/area.Width,(p.Y-area.Y)*Source.H/area.Height);return local.X>=0&&local.Y>=0&&local.X<Source.W&&local.Y<Source.H?new Point((int)local.X,(int)local.Y):new Point(-1,-1);}
    public void SyncPreview(){if(Preview==null)return;var snapshot=Mask.Clone();if(Preview.BaseMask!=null){for(int p=3;p<snapshot.Data.Length;p+=4)snapshot.Data[p]=(byte)((snapshot.Data[p]*Preview.BaseMask.Data[p]+127)/255);}Preview.Layer.Mask=snapshot;}
    protected override void OnRender(DrawingContext dc){dc.DrawRectangle(new SolidColorBrush(Color.FromRgb(20,24,34)),null,new Rect(0,0,ActualWidth,ActualHeight));if(Source==null)return;Rect area=Area();RenderOptions.SetBitmapScalingMode(this,BitmapScalingMode.NearestNeighbor);
        dc.PushClip(new RectangleGeometry(area));
        if(OnScene){SyncPreview();double z=area.Width/Preview.Scene.Width;dc.PushTransform(new TranslateTransform(area.X,area.Y));dc.PushTransform(new ScaleTransform(z,z));SceneRenderer.Draw(dc,Preview.Scene,Preview.Time);dc.Pop();dc.Pop();}
        else{for(double y=area.Y;y<area.Bottom;y+=12)for(double x=area.X;x<area.Right;x+=12)dc.DrawRectangle(new SolidColorBrush(((int)((x-area.X)/12)+(int)((y-area.Y)/12))%2==0?Color.FromRgb(55,62,77):Color.FromRgb(43,49,63)),null,new Rect(x,y,Math.Min(12,area.Right-x),Math.Min(12,area.Bottom-y)));if(Ghost){dc.PushOpacity(.22);dc.DrawImage(Source.Bitmap(),area);dc.Pop();}var shown=Source.Clone();for(int p=3;p<shown.Data.Length;p+=4)shown.Data[p]=(byte)(shown.Data[p]*Mask.Data[p]/255);dc.DrawImage(shown.Bitmap(),area);}
        if(hover.X>=0){double z=area.Width/(OnScene?Preview.Scene.Width:Source.W);Point center=new Point(hover.X+.5,hover.Y+.5);double scale=1;if(OnScene){center=LayerTransform(Preview.Layer,Source,Preview.Time).Transform(center);scale=Preview.Layer.Value(Preview.Layer.Scale,Preview.Layer.EndScale,Preview.Time);}dc.DrawEllipse(null,new Pen(Brushes.White,1),new Point(area.X+center.X*z,area.Y+center.Y*z),Size*z*scale/2,Size*z*scale/2);}dc.Pop();}
}

public sealed class MaskWindow : Window {
    public readonly MaskCanvas Canvas=new MaskCanvas();readonly Stack<Frame> history=new Stack<Frame>();public Frame Result {get{return Canvas.Mask.Clone();}}
    public MaskWindow(Frame source,Frame mask,bool extract,MaskScenePreview preview=null){Title=extract?"Передний план · выделите траву или другой фрагмент":"Маска слоя · исходное изображение сохраняется";Width=1050;Height=760;MinWidth=640;MinHeight=480;Background=new SolidColorBrush(Color.FromRgb(20,24,34));Foreground=Brushes.White;Canvas.Source=source;Canvas.Preview=preview;Canvas.SceneMode=preview!=null;Canvas.Mask=mask==null?LayerMasks.Full(source.W,source.H,!extract):mask.Clone();Canvas.Begin=SaveUndo;var root=new DockPanel {Margin=new Thickness(12)};Content=root;var top=new StackPanel();DockPanel.SetDock(top,Dock.Top);root.Children.Add(top);top.Children.Add(new TextBlock {Text="В режиме «Вся сцена» рисуйте прямо на итоговой картинке. Для уточнения краёв переключитесь на отдельный слой. Изменения видны сразу; проект меняется после применения.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,0,0,8)});var previewRow=new WrapPanel();top.Children.Add(previewRow);previewRow.Children.Add(new TextBlock {Text="Предпросмотр:",Margin=new Thickness(0,4,10,8)});var mode=new ComboBox {ItemsSource=new[]{"Вся сцена · итоговая картинка","Слой · скрытое приглушено","Слой · прозрачность"},SelectedIndex=preview==null?1:0,MinWidth=240,Margin=new Thickness(0,0,10,8)};previewRow.Children.Add(mode);mode.SelectionChanged+=(s,e)=>{if(mode.SelectedIndex==0&&Canvas.Preview==null){mode.SelectedIndex=1;return;}Canvas.SceneMode=mode.SelectedIndex==0;Canvas.Ghost=mode.SelectedIndex==1;Canvas.InvalidateVisual();};var tools=new WrapPanel();top.Children.Add(tools);var picker=new ComboBox {ItemsSource=new[]{"Кисть","Ластик","Прямоугольник","Эллипс","Круг"},SelectedIndex=extract?2:0,MinWidth=160,Margin=new Thickness(0,0,10,8)};Canvas.Tool=(string)picker.SelectedItem;picker.SelectionChanged+=(s,e)=>Canvas.Tool=(string)picker.SelectedItem;tools.Children.Add(picker);var hide=new CheckBox {Content="Скрывать фигурой / кистью",Foreground=Brushes.White,Margin=new Thickness(0,5,10,8)};hide.Click+=(s,e)=>Canvas.Hide=hide.IsChecked==true;tools.Children.Add(hide);MainWindow.AddSizeSlider(top,"Диаметр кисти и ластика, px",Canvas.Size,n=>{Canvas.Size=n;Canvas.InvalidateVisual();});Add(tools,"Показать всё",()=>Replace(LayerMasks.Full(source.W,source.H,true)));Add(tools,"Скрыть всё",()=>Replace(LayerMasks.Full(source.W,source.H,false)));Add(tools,"Инвертировать",()=>{var next=Canvas.Mask.Clone();for(int p=3;p<next.Data.Length;p+=4)next.Data[p]=(byte)(255-next.Data[p]);Replace(next);});Add(tools,"Отменить · Ctrl+Z",Undo);var bottom=new WrapPanel();DockPanel.SetDock(bottom,Dock.Bottom);root.Children.Add(bottom);Add(bottom,extract?"Создать передний слой":"Применить маску",()=>{if(extract&&!Canvas.Mask.Data.Where((v,i)=>i%4==3).Any(v=>v>0)){MessageBox.Show(this,"Сначала выделите видимую область.","Маска");return;}DialogResult=true;});Add(bottom,"Отмена",()=>DialogResult=false);root.Children.Add(Canvas);PreviewKeyDown+=(s,e)=>{if(e.Key==Key.Z&&(Keyboard.Modifiers&ModifierKeys.Control)!=0){Undo();e.Handled=true;}if(e.Key==Key.Escape)DialogResult=false;};}
    void Add(Panel panel,string text,Action action){var b=new Button {Content=text,Margin=new Thickness(0,0,8,8),Padding=new Thickness(10,6,10,6)};b.Click+=(s,e)=>action();panel.Children.Add(b);}
    void SaveUndo(){history.Push(Canvas.Mask.Clone());int limit=Math.Max(2,Math.Min(24,128000000/Canvas.Mask.Data.Length));if(history.Count>limit){var keep=history.Take(limit).Reverse().ToArray();history.Clear();foreach(var item in keep)history.Push(item);}}
    void Replace(Frame frame){SaveUndo();Canvas.Mask=frame;Canvas.InvalidateVisual();}
    void Undo(){if(history.Count==0)return;Canvas.Mask=history.Pop();Canvas.InvalidateVisual();}
}
public sealed partial class CutsceneEditor {
    void InitializeMaskControls(Panel panel){Caption(panel,"Маски и передний план");Button(panel,"Маска слоя · кисть и фигуры",()=>EditMask(false));Button(panel,"Выделить фрагмент → передний слой",()=>EditMask(true));Button(panel,"Снять маску со слоя",()=>{RequireMaskLayer();if(selected.Mask==null)return;Remember();selected.Mask=null;FinishMaskEdit();});panel.Children.Add(Hint("Для травы: выберите фон → «Выделить фрагмент» → выделите прямоугольником или эллипсом → уточните кистью и ластиком. Копия появится поверх всех слоёв в том же месте, с цветами, яркостью и движением исходного фона. Исходный фон сохраняется. Маска редактируется повторно."));}
    void RequireMaskLayer(){if(selected==null||selected.Frames.Count==0)throw new Exception("Выберите слой с изображением.");if(selected.Locked)throw new Exception("Сначала разблокируйте слой.");}
    void EditMask(bool extract){RequireMaskLayer();Stop();EndLiveEdit();var displayed=TemporalStabilizer.Display(selected);int index=(int)Math.Floor(Math.Max(0,time-selected.Start)*selected.Fps);index=selected.Loop?index%displayed.Count:Math.Min(index,displayed.Count-1);var dialog=new MaskWindow(displayed[index],extract?null:selected.Mask,extract,CreateMaskPreview(extract)){Owner=Window.GetWindow(this)};if(dialog.ShowDialog()!=true)return;if(extract){CreateForeground(dialog.Result);}else{Remember();selected.Mask=dialog.Result;}FinishMaskEdit();Tell(extract?"Передний слой создан над остальными. Перемещайте его на холсте; маску можно уточнить повторно.":"Маска применена ко всем кадрам слоя. Ctrl+Z — отменить.");}
    MaskScenePreview CreateMaskPreview(bool extract){var snapshot=Clone(scene);var target=snapshot.Layers[scene.Layers.IndexOf(selected)];var baseMask=extract?target.Mask:null;if(extract){var copy=Clone(scene).Layers[scene.Layers.IndexOf(selected)];copy.Id=Guid.NewGuid().ToString("N");copy.Name+=" · предпросмотр переднего плана";snapshot.Layers.Add(copy);target=copy;}double previewTime=Math.Max(selected.Start,Math.Min(selected.Start+selected.Duration-1e-6,time));return new MaskScenePreview {Scene=snapshot,Layer=target,Time=previewTime,BaseMask=baseMask};}
    void CreateForeground(Frame mask){RequireMaskLayer();if(scene.Layers.Count>=64||scene.Layers.Sum(l=>l.Frames.Sum(f=>(long)f.W*f.H))+selected.Frames.Sum(f=>(long)f.W*f.H)>64000000)throw new Exception("Недостаточно ресурсов для нового слоя.");var copy=Clone(scene).Layers[scene.Layers.IndexOf(selected)];copy.Id=Guid.NewGuid().ToString("N");copy.Name+=" · передний план";copy.LabelColor="#669347";copy.BackgroundLibraryId=null;copy.Mask=mask.Clone();if(selected.Mask!=null)copy.Mask=LayerMasks.Apply(copy.Mask,selected.Mask);Remember();scene.Layers.Add(copy);selected=copy;}
    void FinishMaskEdit(){dirty=true;SceneRenderer.ClearCache();RefreshLayers();ShowLayer();RefreshView();if(WorkspaceEdited!=null)WorkspaceEdited();}
}
}
